"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["24822"],{66682(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>c,frontMatter:()=>i,contentTitle:()=>r,toc:()=>l,assets:()=>h});var a=JSON.parse('{"id":"identity/tianyapost","title":"","description":"http://bbs.tianya.cn/post-stocks-840234-1.shtml","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/identity/tianyapost.md","sourceDirName":"identity","slug":"/identity/tianyapost","permalink":"/en/identity/tianyapost","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"tianyapost","title":"","hide_table_of_contents":true,"sidebar_label":"A tearful tribute to Master Chan (collecting online fragments about Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n / Li Biao)"},"sidebar":"identitySidebar","previous":{"title":"The attending physician recounts Chan\'s final days: hearing his delirious murmurs that night (Oriental Morning Post)","permalink":"/en/identity/dfdaily2"}}'),s=n(74848),o=n(28453);n(66422);let i={id:"tianyapost",title:"",hide_table_of_contents:!0,sidebar_label:"A tearful tribute to Master Chan (collecting online fragments about Ch\xe1n Zh\u014Dng Shu\u014D Ch\xe1n / Li Biao)"},r="Tears for Master Chan \u2014 Collecting Fragments About Chan Zhong Shuo Chan (Li Biao) from the Internet",h={},l=[];function d(e){let t={a:"a",admonition:"admonition",blockquote:"blockquote",em:"em",h1:"h1",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"tears-for-master-chan--collecting-fragments-about-chan-zhong-shuo-chan-li-biao-from-the-internet",children:"Tears for Master Chan \u2014 Collecting Fragments About Chan Zhong Shuo Chan (Li Biao) from the Internet"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.a,{href:"http://bbs.tianya.cn/post-stocks-840234-1.shtml",children:"http://bbs.tianya.cn/post-stocks-840234-1.shtml"})}),"\n"]}),"\n",(0,s.jsx)("div",{class:"tianya-post",children:(0,s.jsx)(t.p,{children:"In the capital markets, thunderous names abound, but none can match Master Chan in inspiring both admiration and genuine heartfelt love and sorrow from countless strangers. I have always hoped that Master Chan's friends and family would write something about him. But memorials to Master Chan online are too few. I have gathered what fragments I could find, filtering out information that might disturb Master Chan and may not be authentic. I hope all who respect Master Chan will refrain from accusations and arguments, for this is not what Master Chan would have wanted to see. This post is solely for remembrance \u2014 please do not disturb Master Chan's spirit in heaven."})}),"\n",(0,s.jsxs)("div",{class:"tianya-post",children:[(0,s.jsx)(t.p,{children:"Master Chan's writing was wild and unrestrained, yet beneath the seemingly cynical mockery and ranting, one could not conceal a Buddha's heart and a Buddha's bones. After completing chemotherapy, Master Chan wrote these words:"}),(0,s.jsx)(t.p,{children:"\"Something as simple as stocks, wasting this ID's precious leisure time \u2014 it's practically a sin. This ID was cooped up in the hospital for so long that raising hell for a few days is only natural. As for those who take issue with this ID going to nightclubs, as if someone who lectures on the Analerta shouldn't go to nightclubs \u2014 that's a waterlogged way of thinking."}),(0,s.jsx)(t.p,{children:"A great bodhisattva manifests in different forms. Among chickens, ducks, geese, and rabbits, there are also great bodhisattvas practicing the bodhisattva path. Who told you there are no great bodhisattvas in nightclubs? Using petty discriminating minds to fathom the boundless Buddhadharma \u2014 such people, just let them be. This ID can't be bothered with them.\""}),(0,s.jsx)(t.p,{children:"If there truly are great bodhisattvas reincarnated, I believe Master Chan must be that bodhisattva wandering through the neon-lit world. Master Chan often affected cold speech, yet could not help but reveal an innate sincerity and goodness. He spent his energy writing tutorials, tirelessly answering netizens' questions. In a market that adheres to the maxim \"those who know don't speak,\" Master Chan's warm selflessness was a realm of greatness beyond ordinary people. The Master Chan of the blog had absolutely no virtue of humility, yet never uttered a single word of self-praise for his acts of guidance. This is how Master Chan explained why he wrote the tutorials:"}),(0,s.jsx)(t.p,{children:"\"Although the theory was personally discovered and invented by this ID, this ID's principle has always been that knowledge belongs to all of humanity. An individual should not hide and hoard it. So this ID gradually made the theory public, solely for the belief that knowledge belongs to all of humanity. This has nothing to do with sympathy or pity. Those who benefit from studying it need not thank this ID, just as you need not thank Euclid for learning plane geometry. As for those who insist on trying to prove plane geometry wrong \u2014 that's fine too. At least it's better than playing mahjong or foolishly losing money in the stock market. The same applies to this ID's theory.\n.......\nFrankly, from this ID's personal standpoint, this ID would thoroughly welcome a massive Asian financial crisis \u2014 at least this ID could then buy houses at half the current price. And this ID has been holding an extremely light position, essentially empty, so this ID wouldn't mind seeing levels of 1,000 or a few hundred points. Just imagine \u2014 CHALCO at 60 yuan, buying it back at 6 yuan, the illness would practically cure itself. But from the standpoint of national interest and the interests of all citizens, that obviously can't happen. And what this ID is doing now actually harms personal interests, but that's not something this ID cares about."}),(0,s.jsx)(t.p,{children:"This ID has long since ceased to have any economic needs. The key is not wanting to see our country and our people bullied by foreigners. This severe illness has revealed a few people's true colors, so all economic dealings with these people will be thoroughly settled after this ID recovers. This ID is here [in Guangzhou], and the financial awareness in this area is still very poor, completely out of step with the city itself. So there may be an opportunity to light a fire in private equity here, leaving some embers behind."}),(0,s.jsx)(t.p,{children:"If you can only go to heaven and cannot descend to hell, then don't talk about the Buddhadharma. Without the cultivation of a tenth-stage bodhisattva, you can't even qualify as a great demon king. If you can't even be a proper demon, how do you expect to become a Buddha? Go grind walls.\""}),(0,s.jsx)(t.p,{children:"Behind the arrogant cold words was a rarely seen warm heart. Before entering the hospital, Master Chan offered this apt self-assessment:"}),(0,s.jsx)(t.p,{children:"\"I am deeply grateful for everyone's concern. Man is not made of wood or stone \u2014 this ID can naturally feel everyone's emotions. After all, those who love poetry and music are naturally prone to overflowing emotions.\""})]}),"\n",(0,s.jsxs)("div",{class:"tianya-post",children:[(0,s.jsx)(t.p,{children:"Regarding Master Chan's birth and death dates, two widely circulated online comments may both be inaccurate."}),(0,s.jsx)(t.p,{children:"Misconception One:\nLi Biao (1969?\u20132008), male.\nGraduated from Guangzhou Guangya High School in 1988.\n1988\u20131992, Sun Yat-sen University, Mathematics Department.\nReaders of Master Chan's blog posts all know that Master Chan entered university at age 17. Since he graduated from Guangya in 1988, his birthday was approximately August 8, 1971."}),(0,s.jsx)(t.p,{children:"Misconception Two:"}),(0,s.jsx)(t.p,{children:"\"At today's Sunday class reunion, two pieces of shocking news:"}),(0,s.jsxs)(t.ol,{children:["\n",(0,s.jsx)(t.li,{children:"A high school classmate of three years who also attended the same university passed away on October 19, 2008, from nasopharyngeal cancer that had spread to the lymphatic system. This person was a legendary figure in China's securities history, and one of the two best operators in my mind.\""}),"\n"]}),(0,s.jsxs)(t.p,{children:['Because the only relatively detailed blog post about Master Chan\'s illness mentions the last visit being on October 24, 2008, and because his passing seems to have been handled very quietly \u2014 the female TCM practitioner who had cared for Master Chan contacted relatives in early November 2008 but was not informed of the bad news \u2014 and classmates learned of his passing at the Guangya High School 120th anniversary reunion without knowing the exact date, the "October 19, 2008" date became a common misconception. The date given by ',(0,s.jsx)(t.em,{children:"Fund Analysis"}),", the magazine Master Chan founded, is: October 31, 2008."]}),(0,s.jsx)(t.p,{children:"Corrected:\nLi Biao (1971.8.8\u20132008.10.31), male.\nGraduated from Guangzhou Guangya High School in 1988.\n1988\u20131992, Sun Yat-sen University, Mathematics Department."})]}),"\n",(0,s.jsxs)("div",{class:"tianya-post",children:[(0,s.jsx)(t.p,{children:"Below is a self-sketch Master Chan wrote using a minor ID:"}),(0,s.jsx)(t.p,{children:"2002-00-00 A quick self-sketch."}),(0,s.jsx)(t.p,{children:"There's another question that must be answered first. I saw the moderator criticize posts for having too many people hiding like turtles these days, afraid to reveal their identity. So let me oblige the moderator and give myself a quick sketch."}),(0,s.jsx)(t.p,{children:"Name: Xiaoren (Little Person). My real name wouldn't ring a bell anyway \u2014 Zhang San, Li Si, whatever you like."}),(0,s.jsx)(t.p,{children:"Marriage: Too early. Even when I'm old enough, I won't be interested \u2014 mainly out of compassion. Imagine: someone as tall and mighty as me, once bound to a single person, would leave all other hopeful admirers in despair. To eliminate self-immolation in China, I won't do such a foolish thing."}),(0,s.jsx)(t.p,{children:"Lovers: Lined up from Earth all the way to Vega. Of course, the Weaving Maid herself is not among them \u2014 she's too old."}),(0,s.jsxs)(t.p,{children:["Hobbies: Aside from hobbies related to English letters, I have research in mathematics, physics, philosophy, music, and other areas. Currently busy turning ",(0,s.jsx)(t.em,{children:"Hamlet"})," into an opera. If there's an opportunity, I'll let you hear my high C."]}),(0,s.jsx)(t.p,{children:"I practice piano three hours daily, vocal training two hours, and spend the remaining time composing, writing poetry, or doing other mischievous things. Good deeds are basically off the table. Tonight I have time to write some thoughts on doggerel verse. If anyone is interested in having an exchange \u2014 crossing swords without crossing streams \u2014 feel free to correspond."})]}),"\n",(0,s.jsxs)("div",{class:"tianya-post",children:[(0,s.jsx)(t.p,{children:"Master Chan wrote in his July 4, 2008 blog post:"}),(0,s.jsxs)(t.p,{children:["\"There's too much to say. If this ID were to write up the full economic theory, it would certainly be thicker than Old Marx's four-volume ",(0,s.jsx)(t.em,{children:"Capital"}),". Come to think of it, though this ID finds mahjong tedious, it seems mahjong might be slightly more fun."]}),(0,s.jsx)(t.p,{children:"Therefore, this ID has decided to celebrate the weekend with mahjong tonight. This ID's younger brother has gone out to set up the mahjong table. Theory is gray \u2014 let the mahjong tree stay evergreen tonight."}),(0,s.jsx)(t.p,{children:"Tomorrow has a football adaptation training session arranged, so there won't be any posts. Please give this ID a break and let me rest for one day. Today's long post should keep you all chewing for a while. This ID is off to steal some private pleasures.\""}),(0,s.jsx)(t.p,{children:"A female footballer then wrote the following text afterward. Its authenticity is uncertain."})]}),"\n",(0,s.jsxs)(t.admonition,{type:"info",children:[(0,s.jsx)(t.p,{children:"The remainder of this page consists of a long collection of blog comments and forum posts from various anonymous users, classmates, and acquaintances who left messages memorializing Chan Zhong Shuo Chan / Li Biao after his passing. The original Chinese text preserves these messages in their raw, emotional form."}),(0,s.jsx)(t.p,{children:"Key themes from the memorial messages include:"}),(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Classmates' recollections from Guangya High School and Sun Yat-sen University"})," \u2014 memories of Li Biao as a mathematical prodigy who competed at senior-high level while still in junior high, his passion for music and composing, his disheveled student appearance, and his mother's death from cancer during his university years."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Confirmation of identity"})," \u2014 multiple independent sources (classmates, the ",(0,s.jsx)(t.em,{children:"Fund Analysis"})," editorial staff, close associates) confirming that Chan Zhong Shuo Chan, Muzi, and Li Biao were the same person."]}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Old Chen"}),' \u2014 repeated mentions of "Old Chen" (\u8001\u9648), the loyal friend who accompanied Master Chan through his final days, as referenced in the blog post "Severe Illness Reveals True Character" (\u5927\u75C5\u8BC6\u4EBA).']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"The vinager comment"}),' \u2014 a message from someone very close to Master Chan: "Because I was too close, I could never face it. Seeing so many people care about him is deeply moving. He also hoped everyone would believe he had gone wandering and would soon return... Many things must wait years before they can be told. Real life is far more cruel than this virtual life. I want to thank his good friend Old Chen for accompanying him to the very end of the road... Biao, go well."']}),"\n"]}),"\n",(0,s.jsxs)(t.li,{children:["\n",(0,s.jsxs)(t.p,{children:[(0,s.jsx)(t.strong,{children:"Reflections on life, death, and legacy"})," \u2014 poetic tributes from devoted followers expressing how Master Chan's writings gave them courage to face life, and how his spirit endures through his work."]}),"\n"]}),"\n"]}),(0,s.jsx)(t.p,{children:"The original Chinese messages with usernames and timestamps are preserved on the Chinese version of this page."})]})]})}function c(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var a=n(96540);let s={},o=a.createContext(s);function i(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:i(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);